100: 	 * Try descriptor-less getrandom(), in non-blocking mode.
101: 	 *
102: 	 * The design of Linux getrandom is broken.  It has an
103: 	 * uninitialized phase coupled with blocking behaviour, which
104: 	 * is unacceptable from within a library at boot time without
105: 	 * possible recovery. See http://bugs.python.org/issue26839#msg267745
106: 	 */
107: 	ret = getentropy_getrandom(buf, len);
108: 	if (ret != -1)
109: 		return (ret);
110: #endif
