118: 	ret = getentropy_urandom(buf, len);
119: 	if (ret != -1)
120: 		return (ret);
121: 
122: #ifdef SYS__sysctl
123: 	/*
124: 	 * Try to use sysctl CTL_KERN, KERN_RANDOM, RANDOM_UUID.
125: 	 * sysctl is a failsafe API, so it guarantees a result.  This
126: 	 * should work inside a chroot, or when file descriptors are
127: 	 * exhausted.
128: 	 *
129: 	 * However this can fail if the Linux kernel removes support
130: 	 * for sysctl.  Starting in 2007, there have been efforts to
131: 	 * deprecate the sysctl API/ABI, and push callers towards use
132: 	 * of the chroot-unavailable fd-using /proc mechanism --
133: 	 * essentially the same problems as /dev/urandom.
134: 	 *
135: 	 * Numerous setbacks have been encountered in their deprecation
136: 	 * schedule, so as of June 2014 the kernel ABI still exists on
137: 	 * most Linux architectures. The sysctl() stub in libc is missing
138: 	 * on some systems.  There are also reports that some kernels
139: 	 * spew messages to the console.
140: 	 */
141: 	ret = getentropy_sysctl(buf, len);
142: 	if (ret != -1)
143: 		return (ret);
144: #endif /* SYS__sysctl */
