216: static int
217: getentropy_urandom(void *buf, size_t len)
218: {
219: 	struct stat st;
220: 	size_t i;
221: 	int fd, cnt, flags;
222: 	int save_errno = errno;
223: 
224: start:
225: 
226: 	flags = O_RDONLY;
227: #ifdef O_NOFOLLOW
228: 	flags |= O_NOFOLLOW;
229: #endif
230: #ifdef O_CLOEXEC
231: 	flags |= O_CLOEXEC;
232: #endif
233: 	fd = open("/dev/urandom", flags, 0);
234: 	if (fd == -1) {
235: 		if (errno == EINTR)
236: 			goto start;
237: 		goto nodevrandom;
238: 	}
239: #ifndef O_CLOEXEC
240: 	fcntl(fd, F_SETFD, fcntl(fd, F_GETFD) | FD_CLOEXEC);
241: #endif
242: 
243: 	/* Lightly verify that the device node looks sane */
244: 	if (fstat(fd, &st) == -1 || !S_ISCHR(st.st_mode)) {
245: 		close(fd);
246: 		goto nodevrandom;
247: 	}
248: 	if (ioctl(fd, RNDGETENTCNT, &cnt) == -1) {
249: 		close(fd);
250: 		goto nodevrandom;
251: 	}
252: 	for (i = 0; i < len; ) {
253: 		size_t wanted = len - i;
254: 		ssize_t ret = read(fd, (char *)buf + i, wanted);
255: 
256: 		if (ret == -1) {
257: 			if (errno == EAGAIN || errno == EINTR)
258: 				continue;
259: 			close(fd);
260: 			goto nodevrandom;
261: 		}
262: 		i += ret;
263: 	}
264: 	close(fd);
265: 	if (gotdata(buf, len) == 0) {
266: 		errno = save_errno;
267: 		return (0);		/* satisfied */
268: 	}
269: nodevrandom:
270: 	errno = EIO;
271: 	return (-1);
