66: static int
67: spt_clearenv(void)
68: {
69: #ifdef HAVE_CLEARENV
70: 	return clearenv();
71: #else
72: 	char **tmp;
73: 
74: 	tmp = malloc(sizeof(*tmp));
75: 	if (tmp == NULL)
76: 		return errno;
77: 
