85: static int
86: spt_copyenv(int envc, char *envp[])
87: {
88: 	char **envcopy;
89: 	char *eq;
90: 	int envsize;
91: 	int i, error;
92: 
93: 	if (environ != envp)
94: 		return 0;
95: 
96: 	/* Make a copy of the old environ array of pointers, in case
97: 	 * clearenv() or setenv() is implemented to free the internal
98: 	 * environ array, because we will need to access the old environ
99: 	 * contents to make the new copy. */
100: 	envsize = (envc + 1) * sizeof(char *);
101: 	envcopy = malloc(envsize);
102: 	if (envcopy == NULL)
103: 		return errno;
104: 	memcpy(envcopy, envp, envsize);
105: 
106: 	error = spt_clearenv();
107: 	if (error) {
108: 		environ = envp;
109: 		free(envcopy);
110: 		return error;
111: 	}
112: 
113: 	for (i = 0; envcopy[i]; i++) {
114: 		eq = strchr(envcopy[i], '=');
115: 		if (eq == NULL)
116: 			continue;
117: 
118: 		*eq = '\0';
119: 		if (setenv(envcopy[i], eq + 1, 1) < 0)
120: 			error = errno;
121: 		*eq = '=';
122: 
123: 		if (error) {
124: #ifdef HAVE_CLEARENV
125: 			/* Because the old environ might not be available
126: 			 * anymore we will make do with the shallow copy. */
127: 			environ = envcopy;
128: #else
129: 			environ = envp;
130: 			free(envcopy);
131: #endif
132: 			return error;
133: 		}
134: 	}
135: 
136: 	/* Dispose of the shallow copy, now that we've finished transfering
137: 	 * the old environment. */
138: 	free(envcopy);
139: 
140: 	return 0;
141: }
