233: void
234: setproctitle_impl(const char *fmt, ...)
235: {
236: 	/* Use buffer in case argv[0] is passed. */
237: 	char buf[SPT_MAXTITLE + 1];
238: 	va_list ap;
239: 	char *nul;
240: 	int len;
241: 
242: 	if (SPT.base == NULL) {
243: 		if (!SPT.warned) {
244: 			warnx("setproctitle not initialized, please either call "
245: 			      "setproctitle_init() or link against libbsd-ctor.");
246: 			SPT.warned = true;
247: 		}
248: 		return;
249: 	}
250: 
251: 	if (fmt) {
252: 		if (fmt[0] == '-') {
253: 			/* Skip program name prefix. */
254: 			fmt++;
255: 			len = 0;
256: 		} else {
257: 			/* Print program name heading for grep. */
258: 			snprintf(buf, sizeof(buf), "%s: ", getprogname());
259: 			len = strlen(buf);
260: 		}
261: 
262: 		va_start(ap, fmt);
263: 		len += vsnprintf(buf + len, sizeof(buf) - len, fmt, ap);
264: 		va_end(ap);
265: 	} else {
266: 		len = snprintf(buf, sizeof(buf), "%s", SPT.arg0);
267: 	}
268: 
269: 	if (len <= 0) {
270: 		SPT.error = errno;
271: 		return;
272: 	}
273: 
274: 	if (!SPT.reset) {
275: 		memset(SPT.base, 0, SPT.end - SPT.base);
276: 		SPT.reset = true;
277: 	} else {
278: 		memset(SPT.base, 0, spt_min(sizeof(buf), SPT.end - SPT.base));
279: 	}
280: 
281: 	len = spt_min(len, spt_min(sizeof(buf), SPT.end - SPT.base) - 1);
282: 	memcpy(SPT.base, buf, len);
283: 	nul = &SPT.base[len];
284: 
285: 	if (nul < SPT.nul) {
286: 		*SPT.nul = '.';
287: 	} else if (nul == SPT.nul && (nul + 1) < SPT.end) {
288: 		*SPT.nul = ' ';
289: 		*++nul = '\0';
290: 	}
291: }
