#include <sys/types.h>
#include <sys/sysctl.h>

#include <errno.h>
#include <stddef.h>

int	getentropy(void *buf, size_t len);

/*
 * Derived from lib/libc/gen/arc4random.c from FreeBSD.
 */
static size_t
getentropy_sysctl(unsigned char *buf, size_t size)
{
	int mib[2];
	size_t len, done;

	mib[0] = CTL_KERN;
	mib[1] = KERN_ARND;
	done = 0;

	do {
		len = size;
		if (sysctl(mib, 2, buf, &len, NULL, 0) == -1)
			return (done);
		done += len;
		buf += len;
		size -= len;
	} while (size > 0);

	return (done);
}

int
getentropy(void *buf, size_t len)
{
	if (len <= 256 && getentropy_sysctl(buf, len) == len)
		return (0);

	errno = EIO;
	return (-1);
